# -*- coding: utf-8 -*-
import re
p='src/lalka-2/work/chapter-01/scaffold.txt'
t={305:'— Усі чоловіки такі. Щойно щось їм сподобається — вже повзуть, мов метелик на вогонь.',306:'— А обидві пані вдома? — спитав Вірський.',307:'Огрядна служниця підозріливо глянула на мене.',308:'— Пан управитель із цим паном?',309:'— З цим паном. Він повірений господаря.',310:'— А він молодий чи старий? — допитувалася вона далі, розглядаючи мене, наче слідчий суддя.',311:'— Та бачиш же, що старий!... — відповів управитель.',312:'— Середнього віку... — втрутився я. (Їй-богу, невдовзі вони й п’ятнадцятирічних хлопців називатимуть старими.)',313:'— Обидві пані вдома, — сказала служниця. — Тільки до молодшої пані щойно прийшла дівчинка на урок. А старша пані у своїй кімнаті.',314:'— Пхе! — пробурмотів управитель. — То скажіть старшій пані...',315:'Ми зайшли до кухні, де стояла ночва, повна мильної води й дитячої білизни. На мотузці біля комина сушилися також дитячі спіднички, сорочечки й шкарпетки. (Одразу видно, коли в помешканні є дитина!)',316:'З-за прочинених дверей ми почули голос уже літньої жінки.',317:'— З управителем?... якийсь пан? — говорила невидима дама. — Може, це Людвичек, бо він мені саме снився...',318:'— Прошу панів пройти, — сказала служниця, відчиняючи двері до вітальні.',319:'Невеличка вітальня перламутрового кольору. Сапфірові меблі, фортепіано, обидва вікна повні білих і рожевих квітів, на стінах — премія Товариства красних мистецтв<sup>597</sup>, на столі лампа зі скляним абажуром у формі тюльпана.',320:'Після похмурої вітальні пані Кжешовської з темними чохлами на меблях тут здалося веселіше. Кімната мала такий вигляд, ніби чекали на гостя. Але надто симетрично розставлені довкола столу меблі свідчили, що гість іще не прийшов.',321:'За хвилю з протилежних дверей вийшла поважного віку пані в попелястій сукні. Мене вразило майже біле волосся довкола худого, але не надто старого й дуже правильного обличчя. Риси цієї пані здавалися мені десь знайомими.',322:'Тим часом управитель застебнув свій забруднений сюртук на два ґудзики й, уклонившись з елегантністю справжнього шляхтича, сказав:',323:'— Дозвольте представити: пан Ржецький, повірений нашого господаря, а також мій колега...',324:'Ми обоє глянули одне одному в очі. Зізнаюся, я трохи здивувався нашому товариству... Вірський помітив це й додав усміхаючись:'}
ls=open(p,encoding='utf-8').read().splitlines();i=-1;o=[]
for l in ls:
 if l.startswith('**PL:**'):i+=1
 if l=='**UA:**' and i in t:l='**UA:** '+t[i]
 o.append(l)
open(p,'w',encoding='utf-8').write('\n'.join(o));print('filled',len(t))
